// ---- src/match.mjs ----
/**
 * Brand matcher for model-logos.
 *
 * Two separate questions are answered here:
 *
 *  1. `matchModelLogo` — which model/brand mark belongs to a provider+model
 *     identity. Used by the composer label and the Settings model rows. This is
 *     the *heuristic*: it only chooses the initial icon, because a per-model
 *     override (stored in the user settings document) always wins in
 *     `resolveModelIcon`.
 *  2. `matchVendorLogo` — which vendor mark belongs to an *official channel*
 *     route id (the Settings → Models provider list and the add-provider
 *     dropdown). Hand-declared custom providers have no vendor mark.
 *
 * One ordered rule table maps a normalized provider/model description to a logo
 * key. Model-level evidence wins over provider-level evidence so an aggregator
 * (`openrouter`, `ollama`, …) shows the brand of the model it serves, while a
 * provider-only rule still covers catalog entries whose model ids are opaque.
 *
 * The matcher is pure: no network, no catalog import, no DOM. The client bundle
 * inlines this module, so it must stay free of imports and of `export` forms
 * other than the ones the build strips (`export const`, `export function`).
 */

/** Logo keys the matcher can return; each one needs a mark in `src/logos-*.mjs`. */
const LOGO_KEYS = Object.freeze([
  'deepseek',
  'openai',
  'claude',
  'gemini',
  'qwen',
  'zhipu',
  'kimi',
  'minimax',
  'mistral',
  'meta',
  'xai',
  'doubao',
  'baidu',
  'tencent',
  'cohere',
  'perplexity',
  'microsoft',
  'nvidia',
  'aws',
  'huggingface',
  'ollama',
  'groq',
  'openrouter',
  'stepfun',
  'yi',
  // Vendor-only marks (official channels that do not match a model family).
  'azure',
  'baseten',
  'cerebras',
  'cloudflare',
  'fireworks',
  'github',
  'opencode',
  'radius',
  'together',
  'typesafe',
  'vercel',
  'xiaomi',
  'antling',
]);

/** Token boundary shared by the word-like rules. */
const B = '(?:^|[\\s/._:·-])';
/** End of token. */
const E = '(?:$|[\\s/._:·-])';

/**
 * Model-identity rules, in priority order: the first hit wins.
 * @type {ReadonlyArray<readonly [string, RegExp]>}
 */
const MODEL_RULES = Object.freeze([
  ['deepseek', /deepseek|deep[-\s]?seek/],
  ['claude', /claude|anthropic/],
  ['openai', new RegExp(`${B}(?:gpt|chatgpt|codex|sora|whisper|davinci|o[1-9])(?:${E}|[-.\\d])`)],
  ['gemini', new RegExp(`gemini|gemma|${B}palm${E}`)],
  ['qwen', /qwen|qwq|qvq|tongyi|通义/],
  ['zhipu', new RegExp(`${B}(?:glm|chatglm|zhipu|z\\.ai)${E}|智谱`)],
  ['kimi', /kimi|moonshot|月之暗面/],
  ['minimax', /minimax|abab|hailuo|海螺/],
  ['mistral', /mistral|mixtral|codestral|magistral|devstral/],
  ['meta', new RegExp(`llama|${B}meta${E}`)],
  ['xai', new RegExp(`${B}(?:grok|xai|x-ai)${E}`)],
  ['doubao', new RegExp(`doubao|豆包|bytedance|skylark|${B}seed${E}`)],
  ['baidu', /ernie|wenxin|文心|baidu/],
  ['tencent', /hunyuan|混元|tencent/],
  ['cohere', new RegExp(`cohere|${B}command[\\s-]?r${E}`)],
  ['perplexity', /perplexity|sonar/],
  ['microsoft', new RegExp(`microsoft|azure|${B}phi[\\s-]?\\d`)],
  ['nvidia', /nvidia|nemotron/],
  ['aws', new RegExp(`amazon|bedrock|${B}(?:nova|titan)${E}`)],
  ['huggingface', new RegExp(`hugging\\s?face|${B}hf${E}`)],
  ['ollama', /ollama/],
  ['groq', /groq/],
  ['openrouter', /openrouter/],
  ['stepfun', new RegExp(`stepfun|step[-\\s]?fun|阶跃|${B}step[-\\s]?\\d`)],
  ['yi', new RegExp(`${B}(?:yi|01\\.?ai|lingyi)${E}|零一`)],
  ['xiaomi', /mimo|小米|xiaomi/],
  ['antling', new RegExp(`${B}ling[-\\s]?(?:mini|flash|plus|pro)${E}|ant[-\\s]?ling|蚂蚁灵光`)],
]);

/**
 * Provider-identity rules, used only when no model rule matched.
 * @type {ReadonlyArray<readonly [string, RegExp]>}
 */
const PROVIDER_RULES = Object.freeze([
  ['deepseek', /deepseek/],
  ['claude', /anthropic|claude/],
  ['openai', /openai/],
  ['gemini', /google|gemini|vertex/],
  ['zhipu', /zai|zhipu|glm|bigmodel|智谱/],
  ['kimi', /moonshot|kimi/],
  ['minimax', /minimax/],
  ['qwen', /qwen|dashscope|aliyun|alibaba|bailian|通义/],
  ['mistral', /mistral/],
  ['meta', /meta|llama/],
  ['xai', /xai|x-ai|grok/],
  ['doubao', /doubao|bytedance|volc|火山/],
  ['baidu', /baidu|ernie|qianfan|千帆/],
  ['tencent', /tencent|hunyuan|腾讯/],
  ['cohere', /cohere/],
  ['perplexity', /perplexity/],
  ['microsoft', /microsoft|azure/],
  ['nvidia', /nvidia/],
  ['aws', /amazon|aws|bedrock/],
  ['huggingface', new RegExp(`hugging\\s?face|${B}hf${E}`)],
  ['ollama', /ollama/],
  ['groq', /groq/],
  ['openrouter', /openrouter/],
  ['stepfun', /stepfun|阶跃/],
  ['yi', /01\.?ai|lingyi|零一/],
  ['azure', /azure/],
  ['baseten', /baseten/],
  ['cerebras', /cerebras/],
  ['cloudflare', /cloudflare/],
  ['fireworks', /fireworks/],
  ['github', /github|copilot/],
  ['opencode', /opencode/],
  ['radius', /radius/],
  ['together', /together/],
  ['typesafe', /typesafe/],
  ['vercel', /vercel/],
  ['xiaomi', /xiaomi|mimo|小米/],
  ['antling', /ant[-\s]?ling|蚂蚁灵光/],
]);

/**
 * Official channel route ids → vendor logo key.
 *
 * This is the *complete* directory of shipped provider routes
 * (`@deepseek-ai/dsh-llm-pi-ai`'s generated catalog plus the two DeepSeek
 * adapters). A route id outside this table is either a hand-declared custom
 * provider (no vendor mark) or a newer channel the UI falls back to a letter
 * tile for.
 * @type {Readonly<Record<string, string>>}
 */
const VENDOR_CHANNELS = Object.freeze({
  'amazon-bedrock': 'aws',
  'ant-ling': 'antling',
  'anthropic': 'claude',
  'azure': 'azure',
  'baseten': 'baseten',
  'cerebras': 'cerebras',
  'cloudflare-ai-gateway': 'cloudflare',
  'cloudflare-workers-ai': 'cloudflare',
  'deepseek': 'deepseek',
  'deepseek-account': 'deepseek',
  'deepseek-official': 'deepseek',
  'fireworks': 'fireworks',
  'github-copilot': 'github',
  'google': 'gemini',
  'google-vertex': 'gemini',
  'groq': 'groq',
  'huggingface': 'huggingface',
  'kimi-coding': 'kimi',
  'meta': 'meta',
  'minimax': 'minimax',
  'minimax-cn': 'minimax',
  'mistral': 'mistral',
  'moonshotai': 'kimi',
  'moonshotai-cn': 'kimi',
  'nvidia': 'nvidia',
  'openai': 'openai',
  'openai-codex': 'openai',
  'opencode': 'opencode',
  'opencode-go': 'opencode',
  'openrouter': 'openrouter',
  'qwen-token-plan': 'qwen',
  'qwen-token-plan-cn': 'qwen',
  'qwen-token-plan-individual': 'qwen',
  'radius': 'radius',
  'together': 'together',
  'typesafe': 'typesafe',
  'vercel-ai-gateway': 'vercel',
  'xai': 'xai',
  'xiaomi': 'xiaomi',
  'xiaomi-token-plan-ams': 'xiaomi',
  'xiaomi-token-plan-cn': 'xiaomi',
  'xiaomi-token-plan-sgp': 'xiaomi',
  'zai': 'zhipu',
  'zai-coding-cn': 'zhipu',
});

/**
 * Ordered vendor rules (route id patterns, first hit wins). Kept as a rule list
 * so a future variant of an official channel (for example a new
 * `xiaomi-token-plan-*` region) still resolves without a table edit.
 * @type {ReadonlyArray<readonly [string, RegExp]>}
 */
const VENDOR_RULES = Object.freeze([
  ['deepseek', /^(?:deepseek(?:-account|-official)?|llm-deepseek)$/],
  ['openai', /^openai(?:-codex)?$/],
  ['claude', /^anthropic$/],
  ['gemini', /^(?:google|google-vertex)$/],
  ['zhipu', /^z(?:ai|ai-coding-cn)$/],
  ['kimi', /^(?:moonshotai|moonshotai-cn|kimi-coding)$/],
  ['minimax', /^minimax(?:-cn)?$/],
  ['qwen', /^qwen-token-plan(?:-cn|-individual)?$/],
  ['xiaomi', /^xiaomi(?:-token-plan-(?:ams|cn|sgp))?$/],
  ['mistral', /^mistral$/],
  ['meta', /^meta$/],
  ['xai', /^xai$/],
  ['nvidia', /^nvidia$/],
  ['aws', /^(?:amazon-bedrock|aws)$/],
  ['azure', /^azure$/],
  ['baseten', /^baseten$/],
  ['cerebras', /^cerebras$/],
  ['cloudflare', /^cloudflare-/],
  ['fireworks', /^fireworks$/],
  ['github', /^github-copilot$/],
  ['opencode', /^opencode(?:-go)?$/],
  ['radius', /^radius$/],
  ['together', /^together$/],
  ['typesafe', /^typesafe$/],
  ['vercel', /^vercel-ai-gateway$/],
  ['antling', /^ant-ling$/],
]);

/** Lowercase and normalize separators so both id and display name are searchable. */
function normalizeModelText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/[_\s]+/g, ' ')
    .trim();
}

/**
 * Describe one label occurrence as the two searchable strings.
 * @param {{ provider?: { id?: string, name?: string }, model?: { id?: string, name?: string } }} input
 * @returns {{ model: string, provider: string }}
 */
function labelTexts(input) {
  const provider = input?.provider ?? {};
  const model = input?.model ?? {};
  return {
    model: normalizeModelText(`${model.id ?? ''} ${model.name ?? ''}`),
    provider: normalizeModelText(`${provider.id ?? ''} ${provider.name ?? ''}`),
  };
}

/**
 * Match one provider/model pair to a logo key.
 * @param {{ provider?: { id?: string, name?: string }, model?: { id?: string, name?: string } }} input
 * @returns {string | null} A key from {@link LOGO_KEYS}, or null when nothing matches.
 */
function matchModelLogo(input) {
  const { model, provider } = labelTexts(input);
  if (model !== '') {
    for (const [key, pattern] of MODEL_RULES) {
      if (pattern.test(model)) return key;
    }
  }
  if (provider !== '') {
    for (const [key, pattern] of PROVIDER_RULES) {
      if (pattern.test(provider)) return key;
    }
  }
  return null;
}

/**
 * Match an official channel route id to its vendor logo key.
 *
 * Exact directory ids win first; the pattern list is the forward-compatible
 * fallback for channel variants. Hand-declared custom providers are not
 * official channels and must be filtered out by the caller before asking.
 * @param {string} providerId - provider route id (`anthropic`, `xiaomi-token-plan-cn`, …).
 * @returns {string | null} A key from {@link LOGO_KEYS}, or null when the id is not a known channel.
 */
function matchVendorLogo(providerId) {
  const id = normalizeModelText(providerId);
  if (id === '') return null;
  const exact = VENDOR_CHANNELS[id];
  if (exact !== undefined) return exact;
  for (const [key, pattern] of VENDOR_RULES) {
    if (pattern.test(id)) return key;
  }
  return null;
}

/**
 * Whether a route id is one of the shipped official channels.
 * @param {string} providerId - provider route id.
 * @returns {boolean}
 */
function isOfficialVendorChannel(providerId) {
  return matchVendorLogo(providerId) !== null;
}

// ---- src/artwork.mjs ----
/**
 * Runtime SVG helpers shared by every plugin surface.
 *
 * This module is pure: no DOM, no imports, no randomness, no side effects. The
 * client build inlines it with the `export` keywords stripped, so only
 * `export const` / `export function` forms are allowed here.
 *
 * `letterTile(text, seed)` is the deterministic fallback mark for providers and
 * models the hand-drawn artwork does not cover. It returns the same
 * `{ title, svg }` shape as the entries in `src/logos-*.mjs`:
 *
 *   - 24x24 rounded-square tile with a flat colour from `LETTER_PALETTE`,
 *     chosen by a stable FNV-1a hash of `seed` (defaults to `text`);
 *   - one or two glyphs derived from `text` and uppercased: two word initials
 *     for multi-word Latin names ("Claude Sonnet" → "CS"), the first two
 *     characters for a single Latin word ("Qwen" → "QW"), and the first
 *     character for non-Latin names such as Chinese ("通义千问" → "通").
 *
 * The glyph is painted as SVG <text> with a system font stack rather than as a
 * hand-drawn path, because the input is arbitrary user/model text and must
 * still render CJK, accented and other non-Latin names sensibly. The tile keeps
 * the same inline-safety rules as the brand marks: no ids, no scripts, no
 * event handlers and no external references — all user text is XML-escaped.
 */

/**
 * Fixed letter-tile palette: dark, saturated hues so the white glyph keeps a
 * comfortable contrast ratio at 14px on both light and dark surfaces.
 */
const LETTER_PALETTE = Object.freeze([
  '#3730A3',
  '#1E40AF',
  '#1D4ED8',
  '#312E81',
  '#5B21B6',
  '#7E22CE',
  '#86198F',
  '#9F1239',
  '#B91C1C',
  '#9A3412',
  '#92400E',
  '#8B5A00',
  '#7C2D12',
  '#4A5568',
  '#374151',
  '#1C1917',
  '#166534',
  '#3F6212',
  '#0F766E',
  '#0E7490',
]);

/** System font stack for tile glyphs (multi-word families may stay unquoted). */
const LETTER_FONT =
  'Segoe UI, Microsoft YaHei, PingFang SC, Hiragino Sans GB, Noto Sans CJK SC, Noto Sans SC, sans-serif';

/** Unicode word runs: letters and digits in any script (CJK included). */
const LETTER_WORDS = /[\p{L}\p{N}]+/gu;

/** Characters that count as "Latin/digit evidence" for glyph selection. */
const LETTER_ASCII = /[A-Za-z0-9]/;

/** Control characters and lone surrogates that are invalid in XML/HTML text. */
const XML_INVALID = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\uD800-\uDFFF\uFFFE\uFFFF]/gu;

/** The five text-significant characters escaped by both helpers. */
const XML_SPECIAL = /[&<>"']/g;

/** Entity table shared by the XML and HTML escapers. */
const SAFE_ENTITIES = Object.freeze({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
});

/**
 * Escape a value for interpolation into XML/SVG text or attribute content.
 * Drops characters XML 1.0 cannot represent instead of emitting them raw.
 * @param {unknown} value
 * @returns {string}
 */
function escapeXml(value) {
  return String(value ?? '')
    .replace(XML_INVALID, '')
    .replace(XML_SPECIAL, (character) => SAFE_ENTITIES[character]);
}

/**
 * Escape a value for interpolation into HTML text or attribute content.
 * Same character set and entity spellings as {@link escapeXml}.
 * @param {unknown} value
 * @returns {string}
 */
function escapeHtml(value) {
  return String(value ?? '')
    .replace(XML_INVALID, '')
    .replace(XML_SPECIAL, (character) => SAFE_ENTITIES[character]);
}

/**
 * Stable 32-bit FNV-1a hash over the code points of `seed`. Deterministic on
 * every JS engine and independent of the tile text, so renaming a label keeps
 * its colour when callers pass an explicit seed.
 * @param {string} seed
 * @returns {number} Unsigned 32-bit hash.
 */
const letterHash = (seed) => {
  let hash = 0x811c9dc5;
  for (const character of seed) {
    hash ^= character.codePointAt(0) ?? 0;
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
};

/** First ASCII letter/digit of a word run, or '' when it has none. */
const letterFirstAscii = (token) => {
  for (const character of token) {
    if (LETTER_ASCII.test(character)) return character;
  }
  return '';
};

/** Every ASCII letter/digit of a word run, in order. */
const letterAsciiChars = (token) =>
  Array.from(token).filter((character) => LETTER_ASCII.test(character));

/**
 * Pick the 1-2 glyphs rendered inside the tile.
 * @param {unknown} text
 * @returns {string}
 */
const letterGlyphs = (text) => {
  const tokens = String(text ?? '').match(LETTER_WORDS) ?? [];
  const latin = tokens.filter((token) => LETTER_ASCII.test(token));
  if (latin.length >= 2) {
    return (letterFirstAscii(latin[0]) + letterFirstAscii(latin[1])).toUpperCase();
  }
  if (latin.length === 1) {
    return letterAsciiChars(latin[0]).slice(0, 2).join('').toUpperCase();
  }
  if (tokens.length > 0) {
    return Array.from(tokens[0])[0] ?? '?';
  }
  const fallback = Array.from(String(text ?? '').trim())[0];
  return fallback ?? '?';
};

/**
 * Build the deterministic fallback mark for an arbitrary name.
 * @param {unknown} text   Display text the glyphs come from.
 * @param {unknown} [seed] Colour seed; defaults to `text`.
 * @returns {{ title: string, svg: string }}
 */
function letterTile(text, seed = text) {
  const title = String(text ?? '').trim() || 'Model';
  const glyphs = Array.from(letterGlyphs(text));
  const fill = LETTER_PALETTE[letterHash(String(seed ?? '')) % LETTER_PALETTE.length];
  // Two glyphs need a smaller size to stay inside the tile; CJK glyphs are
  // full-width, so a single one is already optically large at 13.2 units.
  const fontSize = glyphs.length > 1 ? 11.4 : 13.2;
  return {
    title,
    svg:
      '<svg viewBox="0 0 24 24">' +
      `<rect width="24" height="24" rx="6" fill="${fill}"/>` +
      `<text x="12" y="12" text-anchor="middle" dominant-baseline="central"` +
      ` font-family="${LETTER_FONT}" font-size="${fontSize}" font-weight="700" fill="#FFFFFF">` +
      escapeXml(glyphs.join('')) +
      '</text></svg>',
  };
}

// ---- src/resolve.mjs ----
/**
 * Model icon resolution: explicit user override first, heuristic second.
 *
 * The persisted override document is a nested dictionary:
 *
 *     {
 *       "deepseek-account": { "deepseek-flash": "deepseek" },
 *       "volcengine": { "my-local-model": "letter" | "none" | "qwen" }
 *     }
 *
 * Overrides are keyed by provider id + model id (never the display name alone)
 * so two providers may serve a same-named model with different brands. A value
 * of `none` means the user explicitly disabled the mark; a value of `letter`
 * asks for the generated letter tile (see {@link letterTextFor}) even when no
 * artwork/brand matches — the escape hatch for exotic local models.
 *
 * Pure: no DOM, no network. The client bundle inlines this module.
 */

/** Values that mean "no icon" when persisted. */
const DISABLED = 'none';

/** Override value that asks for the generated letter tile. */
const LETTER = 'letter';

/** Text a letter tile is generated from: display name, then id. */
function letterTextFor(provider, model) {
  const candidates = [model?.name, model?.id, provider?.name, provider?.id];
  for (const candidate of candidates) {
    if (typeof candidate === 'string' && candidate.trim() !== '') return candidate.trim();
  }
  return '?';
}

/** Read a property as an own data property, so `__proto__`/`constructor` are inert. */
function own(object, key) {
  if (object === null || typeof object !== 'object') return undefined;
  return Object.prototype.hasOwnProperty.call(object, key) ? object[key] : undefined;
}

/** Trim an identity part; non-strings become an empty string. */
function idOf(value) {
  return typeof value === 'string' ? value.trim() : '';
}

/** Whether a value is one of the artwork keys. */
function isKnownLogoKey(value) {
  return typeof value === 'string' && LOGO_KEYS.includes(value);
}

/**
 * The explicit override for one provider+model pair.
 * @param {unknown} overrides - persisted override document.
 * @param {string} providerId - provider route id.
 * @param {string} modelId - model id.
 * @returns {string | null} A brand key, `'none'`, `'letter'`, or null when unset.
 */
function overrideIcon(overrides, providerId, modelId) {
  const provider = idOf(providerId);
  const model = idOf(modelId);
  if (provider === '' || model === '') return null;
  const bucket = own(overrides, provider);
  const value = own(bucket, model);
  return typeof value === 'string' && value !== '' ? value : null;
}

/**
 * Return a new override document with one pair set. Passing null/undefined (or
 * the empty string) removes the pair instead.
 * @param {unknown} overrides - current document.
 * @param {string} providerId - provider route id.
 * @param {string} modelId - model id.
 * @param {string | null | undefined} icon - brand key, `'none'`, or a removal value.
 * @returns {Record<string, Record<string, string>>} a new document.
 */
function withOverride(overrides, providerId, modelId, icon) {
  const provider = idOf(providerId);
  const model = idOf(modelId);
  const value = typeof icon === 'string' ? icon.trim() : '';
  if (provider === '' || model === '' || value === '') {
    return withoutOverride(overrides, providerId, modelId);
  }
  const next = copyDocument(overrides);
  const bucket = copyBucket(own(next, provider));
  Object.defineProperty(bucket, model, {
    value,
    enumerable: true,
    writable: true,
    configurable: true,
  });
  Object.defineProperty(next, provider, {
    value: bucket,
    enumerable: true,
    writable: true,
    configurable: true,
  });
  return next;
}

/**
 * Return a new override document with one pair removed.
 * @param {unknown} overrides - current document.
 * @param {string} providerId - provider route id.
 * @param {string} modelId - model id.
 * @returns {Record<string, Record<string, string>>} a new document.
 */
function withoutOverride(overrides, providerId, modelId) {
  const provider = idOf(providerId);
  const model = idOf(modelId);
  if (provider === '' || model === '') return copyDocument(overrides);
  const bucket = own(overrides, provider);
  if (own(bucket, model) === undefined) return copyDocument(overrides);
  const next = copyDocument(overrides);
  const nextBucket = copyBucket(bucket);
  Reflect.deleteProperty(nextBucket, model);
  if (Object.keys(nextBucket).length === 0) Reflect.deleteProperty(next, provider);
  else {
    Object.defineProperty(next, provider, {
      value: nextBucket,
      enumerable: true,
      writable: true,
      configurable: true,
    });
  }
  return next;
}

/**
 * Flatten a document into stable, sorted rows.
 * @param {unknown} overrides - persisted document.
 * @returns {Array<{ providerId: string, modelId: string, icon: string }>}
 */
function flattenOverrides(overrides) {
  if (overrides === null || typeof overrides !== 'object' || Array.isArray(overrides)) return [];
  const rows = [];
  for (const providerId of Object.keys(overrides).sort()) {
    const bucket = own(overrides, providerId);
    if (bucket === null || typeof bucket !== 'object' || Array.isArray(bucket)) continue;
    for (const modelId of Object.keys(bucket).sort()) {
      const icon = own(bucket, modelId);
      if (typeof icon === 'string' && icon !== '') rows.push({ providerId, modelId, icon });
    }
  }
  return rows;
}

/**
 * Resolve the mark for one provider+model identity.
 *
 * Order: explicit override (a known brand key, `letter`, or `none`) → heuristic
 * initial icon → no icon. An unknown/stale override value is ignored, exactly
 * like a deleted artwork key would be.
 * @param {unknown} overrides - persisted override document.
 * @param {{ id?: string, name?: string } | null | undefined} provider - provider identity.
 * @param {{ id?: string, name?: string } | null | undefined} model - model identity.
 * @returns {{ key: string | null, source: 'override' | 'heuristic' | 'none', disabled: boolean, letter: boolean }}
 */
function resolveModelIcon(overrides, provider, model) {
  const explicit = overrideIcon(overrides, provider?.id, model?.id);
  if (explicit === DISABLED) return { key: null, source: 'override', disabled: true, letter: false };
  if (explicit === LETTER) return { key: null, source: 'override', disabled: false, letter: true };
  if (explicit !== null && isKnownLogoKey(explicit)) {
    return { key: explicit, source: 'override', disabled: false, letter: false };
  }
  const heuristic = matchModelLogo({ provider: provider ?? {}, model: model ?? {} });
  if (heuristic !== null) return { key: heuristic, source: 'heuristic', disabled: false, letter: false };
  return { key: null, source: 'none', disabled: false, letter: false };
}

/** Deep-copy a document into a null-prototype-free plain object of own fields. */
function copyDocument(overrides) {
  const out = {};
  if (overrides === null || typeof overrides !== 'object' || Array.isArray(overrides)) return out;
  for (const providerId of Object.keys(overrides)) {
    const bucket = own(overrides, providerId);
    if (bucket === null || typeof bucket !== 'object' || Array.isArray(bucket)) continue;
    Object.defineProperty(out, providerId, {
      value: copyBucket(bucket),
      enumerable: true,
      writable: true,
      configurable: true,
    });
  }
  return out;
}

/** Copy one provider bucket, keeping only non-empty string icons. */
function copyBucket(bucket) {
  const out = {};
  if (bucket === null || typeof bucket !== 'object' || Array.isArray(bucket)) return out;
  for (const modelId of Object.keys(bucket)) {
    const icon = own(bucket, modelId);
    if (typeof icon !== 'string' || icon === '') continue;
    Object.defineProperty(out, modelId, {
      value: icon,
      enumerable: true,
      writable: true,
      configurable: true,
    });
  }
  return out;
}

